import{_ as n,C as e,o as s,c as d,E as a,a7 as c}from"./chunks/framework.FWlv_suP.js";const b=JSON.parse('{"title":"Card Nest Privacy Policy","description":"Privacy Policy for Card Nest, presented within Policy Hub.","frontmatter":{"title":"Card Nest Privacy Policy","description":"Privacy Policy for Card Nest, presented within Policy Hub."},"headers":[],"relativePath":"apps/card-nest/privacy.md","filePath":"apps/card-nest/privacy.md"}'),l={name:"apps/card-nest/privacy.md"};function p(u,r,h,m,y,f){const t=e("AppBreadcrumbs"),o=e("AppSubnav"),i=e("CopyStandaloneUrl");return s(),d("div",null,[a(t,{"app-id":"card-nest",current:"Privacy Policy"}),a(o,{"app-id":"card-nest"}),a(i,{path:"/privacy/card-nest",label:"Copy Play Store URL","copied-label":"Play Store URL copied","document-name":"Card Nest privacy policy"}),r[0]||(r[0]=c('<h1 id="privacy-policy-for-card-nest" tabindex="-1">Privacy Policy for Card Nest <a class="header-anchor" href="#privacy-policy-for-card-nest" aria-label="Permalink to &quot;Privacy Policy for Card Nest&quot;">​</a></h1><p><strong>Effective Date:</strong> August 1, 2026<br><strong>Last Updated:</strong> August 1, 2026</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Card Nest is an offline-first credit-card and personal-finance organizer developed by <strong>Anand Raja</strong>. It does not require an account and does not include advertising, analytics, tracking, or developer-operated cloud sync.</p><h2 id="information-stored-on-your-device" tabindex="-1">Information Stored on Your Device <a class="header-anchor" href="#information-stored-on-your-device" aria-label="Permalink to &quot;Information Stored on Your Device&quot;">​</a></h2><p>Card Nest stores the information you enter in a local SQLite database, which may include:</p><ul><li>Card nicknames, issuers, networks, last digits, limits, statement and due-date rules, expiry dates, annual fees, benefits, important links, and linked-card groups</li><li>Optional full card numbers and CVVs</li><li>Transactions, merchants, amounts, dates, categories, payment sources, notes, tax information, recurring rules, and receipt images</li><li>Income, budgets, category limits, cash or account balances, loan and EMI details, reminder settings, and report history</li><li>Optional profile title and name, theme, date format, currency, and other app preferences</li></ul><p>The developer does not receive this database.</p><h2 id="sensitive-card-data-and-app-lock" tabindex="-1">Sensitive Card Data and App Lock <a class="header-anchor" href="#sensitive-card-data-and-app-lock" aria-label="Permalink to &quot;Sensitive Card Data and App Lock&quot;">​</a></h2><p>Optional full card numbers and CVVs are encrypted locally with AES-GCM using a random key stored in Card Nest&#39;s local app preferences. These values are hidden by default and excluded from masked CSV and PDF reports.</p><p>An optional application PIN is stored as a salted PBKDF2-SHA-256 hash; the PIN itself is not stored. Optional Android biometric unlock asks Android to verify an enrolled biometric before opening the app. Card Nest does not receive or store biometric templates.</p><p>The PIN and biometric features control access to the app interface. They do not derive the card-data encryption key and are not a replacement for Android device encryption or a secure device lock. No security measure can guarantee complete protection on a compromised device.</p><h2 id="receipt-images" tabindex="-1">Receipt Images <a class="header-anchor" href="#receipt-images" aria-label="Permalink to &quot;Receipt Images&quot;">​</a></h2><p>You may use the Android camera, system photo picker, or browser camera to attach receipt images to transactions. Selected images are processed and stored locally with Card Nest data. Camera access occurs only when you choose the camera action and grant permission. The system photo picker provides access only to images you select.</p><h2 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to &quot;Notifications&quot;">​</a></h2><p>If you enable reminders and grant notification permission, Card Nest schedules Android notifications for payment due dates, annual fees, and card expiry. Notification content can include a card nickname, masked last digits, amount, and relevant date. It does not include a full card number or CVV.</p><p>Android stores and displays scheduled notification content outside Card Nest&#39;s SQLite database. Its visibility on the lock screen depends on your Android notification settings.</p><h2 id="backup-restore-and-exports" tabindex="-1">Backup, Restore, and Exports <a class="header-anchor" href="#backup-restore-and-exports" aria-label="Permalink to &quot;Backup, Restore, and Exports&quot;">​</a></h2><p>Card Nest <code>.cnbak</code> backups contain the local database and are encrypted with AES-256-GCM using a key derived from a separate backup passphrase with PBKDF2-SHA-256. The passphrase is not stored and cannot be recovered by the developer.</p><p>You choose where to save or share a backup. If you select a cloud-storage or sharing provider, that provider receives the encrypted file under its own privacy practices.</p><p>CSV and PDF exports are designed for reports and contain readable financial and transaction information. Masked exports exclude full card numbers and CVVs, but may still contain card nicknames, last digits, merchants, amounts, categories, dates, sources, income, budgets, and notes. Protect exported files and delete copies you no longer need.</p><h2 id="network-requests-and-third-party-services" tabindex="-1">Network Requests and Third-Party Services <a class="header-anchor" href="#network-requests-and-third-party-services" aria-label="Permalink to &quot;Network Requests and Third-Party Services&quot;">​</a></h2><p>Card Nest&#39;s interface references Google Fonts. When the app has internet access, the device may request font resources from Google. Google may receive standard connection information such as the device IP address, user agent, request time, and requested resource. Google&#39;s processing is governed by the <a href="https://policies.google.com/privacy" target="_blank" rel="noreferrer">Google Privacy Policy</a>.</p><p>The core database, cards, transactions, calculations, reports, and reminders do not require a developer server or cloud account.</p><h2 id="information-collected-by-the-developer" tabindex="-1">Information Collected by the Developer <a class="header-anchor" href="#information-collected-by-the-developer" aria-label="Permalink to &quot;Information Collected by the Developer&quot;">​</a></h2><p>The developer does not receive Card Nest database contents, card details, receipts, financial records, PINs, backup passphrases, device identifiers, or usage telemetry. Card Nest does not sell user information.</p><p>If you contact the developer by email, the information you voluntarily include is used to respond to your support or privacy request. Do not email card numbers, CVVs, PINs, receipts, backups, or unredacted financial exports.</p><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><p>Depending on the features you use and Android version, Card Nest may use:</p><ul><li>Camera permission for receipt capture</li><li>System photo-picker access for receipt images you select</li><li>Notification permission for optional reminders</li><li>Android biometric authentication for optional app unlock</li><li>File or document access for backups and report exports</li><li>Internet access for Google-hosted font resources</li></ul><p>The reviewed features do not require location, contacts, phone, SMS, or broad gallery access.</p><h2 id="retention-and-deletion" tabindex="-1">Retention and Deletion <a class="header-anchor" href="#retention-and-deletion" aria-label="Permalink to &quot;Retention and Deletion&quot;">​</a></h2><p>Card Nest data remains on the device until you delete individual records, run a history cleanup, select <strong>Delete all data</strong>, clear Android app storage, or uninstall the app. History cleanup can remove transactions older than the selected 3, 5, 7, or 10-year period.</p><p>Deleting all app data does not remove backup, CSV, or PDF files saved or shared outside Card Nest. Delete those files separately from every destination.</p><p>There is no developer-operated Card Nest account or cloud database to delete by email.</p><h2 id="children-s-privacy" tabindex="-1">Children&#39;s Privacy <a class="header-anchor" href="#children-s-privacy" aria-label="Permalink to &quot;Children&#39;s Privacy&quot;">​</a></h2><p>Card Nest is not designed to collect children&#39;s personal information through a developer-operated service.</p><h2 id="changes-to-this-policy" tabindex="-1">Changes to This Policy <a class="header-anchor" href="#changes-to-this-policy" aria-label="Permalink to &quot;Changes to This Policy&quot;">​</a></h2><p>This policy may be updated when Card Nest&#39;s features or data practices change. The dates above will be revised when an updated policy is published.</p><h2 id="contact" tabindex="-1">Contact <a class="header-anchor" href="#contact" aria-label="Permalink to &quot;Contact&quot;">​</a></h2><ul><li><strong>Developer:</strong> Anand Raja</li><li><strong>Email:</strong> <a href="mailto:anand.official.in@gmail.com" target="_blank" rel="noreferrer">anand.official.in@gmail.com</a></li></ul>',41))])}const g=n(l,[["render",p]]);export{b as __pageData,g as default};
